{
  "items": [
    {
      "title": "Destatis GENESIS-Online: University Students in Germany by Semester, Nationality and Gender",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/table/21311-0001",
      "justification": "Official dataset from the German Federal Statistical Office (Destatis) containing historical university enrollment statistics, including the entire 2010s. Provides student counts by semester, nationality and gender. Particularly useful for analyzing changes in higher education participation, gender distribution and international student enrollment in Germany between 2010 and 2019."
    },
    {
      "title": "DZHW Pooled Data Set: 10th–21st Social Survey of German Students (1982–2016)",
      "url_or_doi": "https://doi.org/10.21249/DZHW:ssypool:3.1.0",
      "justification": "Longitudinally harmonized collection of cross-sectional student surveys conducted by the German Centre for Higher Education Research and Science Studies (DZHW). Includes observations from 2012 and 2016, making it particularly relevant to the 2010s. Covers students' socioeconomic backgrounds, financial circumstances, employment, accommodation, educational experiences and access to higher education. Suitable for examining inequalities and changes in student living conditions."
    },
    {
      "title": "Eurostat: Students Enrolled in Tertiary Education by Education Level, Programme Orientation, Gender, Institution Type and Study Intensity",
      "url_or_doi": "https://doi.org/10.2908/EDUC_UOE_ENRT01",
      "justification": "Official Eurostat dataset covering tertiary education enrollment across European countries, including Germany. Historical coverage extends from 2005 onward, encompassing the entire 2010–2019 period. Provides annual enrollment statistics differentiated by education level, gender, institutional characteristics and participation intensity. Particularly useful for comparing Germany's higher education expansion with developments elsewhere in Europe."
    },
    {
      "title": "Eurostat: Students Enrolled in Tertiary Education by Education Level, Programme Orientation, Gender and Field of Education",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/product/page/educ_uoe_enrt03",
      "justification": "Official European statistical dataset containing higher education enrollment figures for Germany and other European countries from 2012 onward. Includes breakdowns by educational level, gender and academic discipline. Useful for investigating trends in STEM education, humanities, social sciences and gender differences across academic fields during the 2010s."
    },
    {
      "title": "BIBB: Continuing Vocational Training Survey (CVTS)",
      "url_or_doi": "https://www.bibb.de/de/9228.php",
      "justification": "Official source from Germany's Federal Institute for Vocational Education and Training (BIBB) describing the Continuing Vocational Training Survey. Includes survey waves covering 2010 and 2015, directly matching the requested period. Collects information about employer-provided continuing education, training expenditure, employee participation, organizational training strategies and barriers to professional development. Particularly relevant for researching further education and workplace learning in Germany."
    },
    {
      "title": "BIBB Research Data Centre: Vocational Education, Employment and Continuing Training Microdata",
      "url_or_doi": "https://www.bibb.de/en/53.php",
      "justification": "Official research data portal providing access to individual-level and establishment-level datasets covering vocational education, employment and continuing professional training in Germany. Includes the 2012 and 2018 waves of the BIBB/BAuA Employment Survey, both documented in English. Suitable for studying relationships between educational qualifications, occupational skills, employment conditions and participation in continuing education during the 2010s. Some microdata require research access applications."
    },
    {
      "title": "BIBB: Participation of Companies in Continuing Vocational Education and Training",
      "url_or_doi": "https://www.bibb.de/en/713.php",
      "justification": "Official BIBB resource connecting researchers to German and European datasets on company participation in continuing vocational education. Includes information about the 2010 Continuing Vocational Training Survey and supplementary company surveys. Useful for examining employer investment in professional development, workplace learning practices and differences between companies in their provision of further education."
    },
    {
      "title": "BIBB: Establishment Panel on Qualification and Competence Development, 2011–2017",
      "url_or_doi": "https://www.bibb.de/en/53.php",
      "justification": "German establishment-level panel data covering vocational training, employee qualifications and continuing professional education during 2011–2017. The survey population includes German establishments with employees subject to social insurance contributions. Particularly suitable for analyzing how firms' training investments, recruitment practices and skills-development strategies evolved during the 2010s. Dataset documentation and access information are available through the BIBB Research Data Centre."
    },
    {
      "title": "DZHW: 20th Social Survey of Students in Germany (2012)",
      "url_or_doi": "https://www.dzhw.eu/en/forschung/projekt?pr_id=650",
      "justification": "National survey conducted during the summer semester of 2012, with 15,128 participating students. Provides detailed information about the socioeconomic circumstances of students enrolled in German higher education institutions. Topics include student finances, educational backgrounds, employment and living arrangements. The project page provides access to reports and statistical tabulations, including downloadable Excel tables. Particularly valuable for establishing an early-2010s benchmark."
    },
    {
      "title": "DZHW: 21st Social Survey of Students in Germany (2016)",
      "url_or_doi": "https://www.dzhw.eu/en/forschung/projekt?pr_id=650",
      "justification": "National student survey conducted in the summer semester of 2016. Covers economic and social conditions in German higher education, including educational access, student financing, accommodation and employment. Statistical tables are available through the project page, while harmonized survey microdata are included in the DZHW pooled Social Survey dataset. Useful for comparing student experiences in the middle of the 2010s with earlier survey waves."
    },
    {
      "title": "BIBB: VET Data Report Germany — Historical Vocational Education and Training Statistics",
      "url_or_doi": "https://www.bibb.de/en/210294.php",
      "justification": "Official collection of annual empirical reports on vocational education and training in Germany, including editions published throughout the 2010s. Contains statistical indicators and historical analyses concerning apprenticeship participation, training contracts, transitions from school to vocational education, qualifications and continuing professional development. Although primarily a statistical reporting collection rather than a standalone downloadable microdataset, it offers substantial quantitative information for analyzing further education and vocational training trends between 2010 and 2019."
    },
    {
      "title": "GOVET: Data and Statistics on Vocational Education and Training in Germany",
      "url_or_doi": "https://www.govet.international/en/54886.php",
      "justification": "Official German vocational education statistics portal providing historical statistical collections and reports from BIBB and federal government sources. Includes VET Data Reports from 2015, 2016–2017, 2018 and 2019. Covers participation in vocational education, apprenticeship systems, workforce qualifications and continuing training. Useful as a discovery resource for quantitative historical information on Germany's further education and vocational training sector during the 2010s."
    },
    {
      "title": "Eurostat: Students Enrolled in Tertiary Education — European Open Data Catalogue",
      "url_or_doi": "https://data.europa.eu/data/datasets/deevvh1xp675tzwutz8w?locale=en",
      "justification": "European Union open-data catalogue record providing access to official Eurostat tertiary education enrollment statistics, including Germany and the 2010–2019 period. Offers dataset downloads in machine-readable formats, including CSV, TSV and SDMX, alongside metadata and visualization tools. Especially useful for researchers requiring reproducible quantitative analysis, standardized international comparisons or integration with statistical software."
    }
  ]
}
